<script setup lang="ts">
import type {ScopedCredential,ScopedCategory} from '~~/shared/utils/vault-sources'
const props=defineProps<{entry:ScopedCredential|null;subscriptionEntries?:ScopedCredential[];open:boolean;categories:ScopedCategory[];links:{id:string;label:string;target:string}[];busy:boolean}>()
const emit=defineEmits<{close:[];edit:[entry:ScopedCredential];copy:[value:string];renew:[entry:ScopedCredential,fieldId:string]}>()
const {accounts,revealed,toggle,safeUrl}=useCredentialDetails(props)
</script>
<template><UModal :open="open" :title="entry?.title||'Карточка'" description="Все данные карточки и прикреплённые изображения." :ui="{content:'sm:max-w-3xl',body:'min-w-0 overflow-y-auto',footer:'justify-end'}" @update:open="value=>{if(!value)emit('close')}"><template #body><div v-if="entry" class="credential-details">
 <a v-if="safeUrl(entry.url)" :href="safeUrl(entry.url)" target="_blank" rel="noopener noreferrer" class="detail-site">{{ entry.url }}<UIcon name="i-lucide-external-link"/></a>
 <div class="detail-tags"><span v-for="(name,i) in entry.vaultNames||[entry.vaultName]" :key="i"><UIcon name="i-lucide-vault"/>{{ name }}</span><span v-for="category in categories" :key="category.filterId">{{ category.name }}</span></div>
 <section v-for="account in accounts" :key="account.id" class="detail-account"><h3>{{ account.label }}</h3><div class="detail-value"><span>Логин</span><strong>{{ account.username||'Не указан' }}</strong><UButton color="neutral" variant="ghost" icon="i-lucide-copy" :disabled="!account.username" :aria-label="`Скопировать логин: ${account.label}`" @click="emit('copy',account.username)"/></div><div class="detail-value"><span>Пароль</span><strong>{{ account.password?(revealed.includes(account.id)?account.password:'••••••••••••'):'Не указан' }}</strong><UButton color="neutral" variant="ghost" :icon="revealed.includes(account.id)?'i-lucide-eye-off':'i-lucide-eye'" :disabled="!account.password" :aria-label="`Показать или скрыть пароль: ${account.label}`" @click="toggle(account.id)"/><UButton color="neutral" variant="ghost" icon="i-lucide-copy" :disabled="!account.password" :aria-label="`Скопировать пароль: ${account.label}`" @click="emit('copy',account.password)"/></div></section>
 <section v-if="entry.notes" class="detail-notes"><h3>Заметка</h3><p>{{ entry.notes }}</p></section>
 <section v-for="field in entry.customFields?.filter(field=>field.type!=='subscription')" :key="field.id" class="detail-custom-field"><div class="detail-value"><span>{{ field.label }}</span><a v-if="field.type==='url'&&safeUrl(field.value)" :href="safeUrl(field.value)" target="_blank" rel="noopener noreferrer">{{ field.value }}</a><strong v-else>{{ field.type==='secret'&&!revealed.includes(field.id)?'••••••••':field.value||'—' }}</strong><UButton v-if="field.type==='secret'" color="neutral" variant="ghost" icon="i-lucide-eye" :aria-label="`Показать или скрыть: ${field.label}`" @click="toggle(field.id)"/><UButton color="neutral" variant="ghost" icon="i-lucide-copy" :aria-label="`Скопировать: ${field.label}`" :disabled="!field.value" @click="emit('copy',field.value)"/></div></section>
 <SubscriptionSummary :entry="entry" :entries="subscriptionEntries" :busy="busy" @renew="(entry,id)=>emit('renew',entry,id)"/>
 <section v-if="links.length" class="detail-notes"><h3>Связи с карточками</h3><p v-for="link in links" :key="link.id">{{ link.label }} · {{ link.target }}</p></section>
 <section v-if="entry.images?.length" class="detail-gallery"><figure v-for="image in entry.images" :key="image.id"><img :src="image.data" :alt="image.name"/><figcaption>{{ image.name }}</figcaption></figure></section>
 </div></template><template #footer><UButton color="neutral" variant="outline" label="Закрыть" @click="emit('close')"/><UButton v-if="entry" icon="i-lucide-pencil" label="Изменить карточку" :disabled="busy" @click="emit('edit',entry)"/></template></UModal></template>
